function drawWorld(time){drawBackground(time);let sorted=items.slice().sort((a,b)=>b.z-a.z);sorted.forEach(o=>o.type==='coin'?drawCoin(o):drawObstacle(o));let x=roadX(lane,0),y=H*.84;drawFlavio(x,y,clamp(Math.min(W/450,H/650),.68,1.15),jump>0?Math.sin((1-jump/0.8)*Math.PI)*55:0)}
function start(){items=[];particles=[];lane=targetLane=1;runTime=distance=coinCount=0;speed=14;spawnIn=.55;jump=slide=shake=0;mode='running';overlay.classList.add('hidden');$('#hint').style.opacity='1';$('#distance').textContent='0 m';$('#coins').textContent='0';last=performance.now();requestAnimationFrame(frame)}
function end(){if(mode!=='running')return;mode='over';shake=12;best=Math.max(best,Math.floor(distance));localStorage.setItem('metroBest',best);$('#best').textContent=best+' m';$('#title').innerHTML='FIM DE LINHA!<br><span style="color:#f4d447">'+Math.floor(distance)+' METROS</span>';$('#message').textContent=`Você pegou ${coinCount} moedas. Bora tentar bater seu recorde?`;$('#play').textContent='CORRER DE NOVO';overlay.classList.remove('hidden')}
function addPattern(){let laneId=Math.floor(Math.random()*3),r=Math.random();if(r<.44){items.push({type:'obstacle',kind:'train',lane:laneId,z:34})}else if(r<.72){items.push({type:'obstacle',kind:'barrier',lane:laneId,z:34})}else{items.push({type:'obstacle',kind:'sign',lane:laneId,z:34})}
// a short coin trail often offers a risky alternate route
if(Math.random()<.66){let coinLane=(laneId+(Math.random()<.5?1:2))%3;for(let i=0;i<5;i++)items.push({type:'coin',lane:coinLane,z:35+i*2.15,phase:Math.random()*6})}}
function action(a){if(mode!=='running')return;if(a==='left')targetLane=clamp(targetLane-1,0,2);if(a==='right')targetLane=clamp(targetLane+1,0,2);if(a==='jump'&&jump<=0&&slide<=0)jump=.78;if(a==='slide'&&jump<=0)slide=.58}
function frame(now){if(mode!=='running')return;let dt=Math.min((now-last)/1000,.035);last=now;runTime+=dt;distance+=speed*dt*.72;speed=Math.min(27,14+distance*.013);lane+=(targetLane-lane)*Math.min(1,dt*13);if(jump>0)jump=Math.max(0,jump-dt);if(slide>0)slide=Math.max(0,slide-dt);spawnIn-=dt;if(spawnIn<=0){addPattern();spawnIn=Math.max(.56,1.08-(speed-14)*.027)+Math.random()*.32}
for(let o of items)o.z-=speed*dt;for(let o of items){if(o.z<1.25&&o.z>-.2&&Math.round(lane)===o.lane){if(o.type==='coin'){coinCount++;o.z=-10;$('#coins').textContent=coinCount;particles.push({x:roadX(o.lane,0),y:H*.72,life:.45})}else{let safe=o.kind==='barrier'?jump>0.18:o.kind==='sign'?slide>0.13:false;if(!safe){end();break}}}}
items=items.filter(o=>o.z>-.8);for(let p of particles)p.life-=dt;particles=particles.filter(p=>p.life>0);$('#distance').textContent=Math.floor(distance)+' m';ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.83}drawWorld(runTime);for(let p of particles){ctx.globalAlpha=p.life*2;ctx.fillStyle='#ffea69';ctx.font='900 22px system-ui';ctx.textAlign='center';ctx.fillText('✦',p.x,p.y-p.life*30)}ctx.restore();requestAnimationFrame(frame)}
$('#play').addEventListener('click',()=>{if(soundOn)beep(540,.07);start()});
function beep(freq,duration){try{audio??=new AudioContext();let osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=freq;gain.gain.setValueAtTime(.055,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch{}}
$('#sound').addEventListener('click',()=>{soundOn=!soundOn;$('#sound').textContent=soundOn?'♫':'♪';if(soundOn)beep(660,.1)});
addEventListener('keydown',e=>{let map={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'jump',w:'jump',W:'jump',' ':'jump',ArrowDown:'slide',s:'slide',S:'slide'};if(map[e.key]){e.preventDefault();action(map[e.key])}if((e.key==='Enter'||e.key===' ')&&mode!=='running')start()},{passive:false});
document.querySelectorAll('.ctrl').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();action(b.dataset.action)})});let touchStart=null;canvas.addEventListener('pointerdown',e=>{touchStart={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{if(!touchStart)return;let dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;if(Math.abs(dx)>Math.abs(dy))action(dx<0?'left':'right');else action(dy<0?'jump':'slide')});
// idle scene
function idle(){if(mode==='running')return;drawWorld(performance.now()/1000);requestAnimationFrame(idle)}requestAnimationFrame(idle);
})();
</script>
</body>
</html>

